// Generate the complete Unicode 17.0 grapheme conformance suite with Node.
// This script is tooling only; nts never builds or runs it.
//
// node tooling/unicode-cases/graphemes.ts [--data-dir=/path/to/ucd] [--output-dir=/path] [--check]
// Without --data-dir, the hash-pinned official input is fetched in memory.
// --check compares every generated byte and the complete filename inventory.
// Existing differing cases are never overwritten: recorded cases are immutable.
// When reviewing a pin upgrade, update the version and hash constants together,
// then use a clean --output-dir to inspect new cases without changing old ones.

import { createHash } from "node:crypto";
import { existsSync, mkdirSync, readFileSync, readdirSync, writeFileSync } from "node:fs";
import { join, resolve } from "node:path";

const NODE = "24.20.0";
const UNICODE = "17.0";
const ICU = "78.3";
const DATA_VERSION = "17.0.0";
const SOURCE = "https://www.unicode.org/Public/17.0.0/ucd/auxiliary/GraphemeBreakTest.txt";
const SHA256 = "e2d134d2c52919bace503ebb6a551c1855fe1a1faec18478c78fff254a1793ec";
const ROOT = resolve(import.meta.dirname, "../..");
const OUTPUT = join(ROOT, "tests/typescript/unicode");
const PREFIX = "graphemes-";
const CHUNK_ROWS = 128;
type Row = { line: number; input: string; boundaries: number[]; expected: string[] };
type Options = { check: boolean; dataDir: string | undefined; outputDir: string };

function requireOracle(): void {
  if (process.versions.node !== NODE || process.versions.unicode !== UNICODE || process.versions.icu !== ICU) {
    throw new Error(`Grapheme generator requires Node ${NODE}, Unicode ${UNICODE}, ICU ${ICU}; ` +
      `found Node ${process.versions.node}, Unicode ${process.versions.unicode}, ICU ${process.versions.icu}`);
  }
  if (!readFileSync(join(ROOT, ".tool-versions"), "utf8").split(/\r?\n/).includes(`nodejs ${NODE}`)) {
    throw new Error(`The repository Node pin is no longer ${NODE}; review this generator and its data together`);
  }
}

function options(): Options {
  let check = false;
  let dataDir: string | undefined;
  let outputDir = OUTPUT;
  for (const argument of process.argv.slice(2)) {
    if (argument === "--check") check = true;
    else if (argument.startsWith("--data-dir=") && argument.length > 11) dataDir = resolve(argument.slice(11));
    else if (argument.startsWith("--output-dir=") && argument.length > 13) outputDir = resolve(argument.slice(13));
    else throw new Error(`Unknown argument ${argument}`);
  }
  return { check, dataDir, outputDir };
}

async function sourceText(dataDir: string | undefined): Promise<string> {
  let bytes: Uint8Array;
  if (dataDir !== undefined) bytes = readFileSync(join(dataDir, "GraphemeBreakTest.txt"));
  else {
    const response = await fetch(SOURCE);
    if (!response.ok) throw new Error(`Fetching ${SOURCE} failed: HTTP ${response.status}`);
    bytes = new Uint8Array(await response.arrayBuffer());
  }
  const digest = createHash("sha256").update(bytes).digest("hex");
  if (digest !== SHA256) throw new Error(`GraphemeBreakTest ${DATA_VERSION} SHA-256 mismatch: ${digest}`);
  return new TextDecoder("utf-8", { fatal: true }).decode(bytes);
}

function literal(text: string): string {
  let result = '"';
  for (let i = 0; i < text.length; i++) result += "\\u" + text.charCodeAt(i).toString(16).toUpperCase().padStart(4, "0");
  return result + '"';
}

function parseAndVerify(text: string): { header: string; rows: Row[] } {
  const rows: Row[] = [];
  const segmenter = new Intl.Segmenter("en", { granularity: "grapheme" });
  const lines = text.split("\n");
  let headerLines = -1;
  for (let index = 0; index < lines.length; index++) {
    const body = lines[index].split("#")[0].trim();
    if (body === "") continue;
    if (headerLines < 0) headerLines = index;
    const tokens = body.split(/\s+/);
    if (tokens.length % 2 !== 1 || tokens[0] !== "\u00F7" || tokens[tokens.length - 1] !== "\u00F7") {
      throw new Error(`Malformed grapheme boundary row at line ${index + 1}`);
    }
    const boundaries: number[] = [];
    let input = "";
    for (let at = 0; at < tokens.length; at += 2) {
      if (tokens[at] === "\u00F7") boundaries.push(input.length);
      else if (tokens[at] !== "\u00D7") throw new Error(`Unexpected grapheme marker at line ${index + 1}`);
      if (at + 1 < tokens.length) {
        const token = tokens[at + 1];
        if (!/^[0-9A-F]{4,6}$/.test(token)) throw new Error(`Malformed grapheme code point at line ${index + 1}: ${token}`);
        const point = Number.parseInt(token, 16);
        if (point > 0x10ffff) throw new Error(`Out-of-range grapheme code point at line ${index + 1}: ${token}`);
        input += String.fromCodePoint(point);
      }
    }
    const actual = Array.from(segmenter.segment(input));
    if (actual.length + 1 !== boundaries.length) {
      throw new Error(`Node disagrees with GraphemeBreakTest ${DATA_VERSION} line ${index + 1}: ` +
        `${actual.length} segments instead of ${boundaries.length - 1}`);
    }
    for (let at = 0; at < actual.length; at++) {
      const expected = input.slice(boundaries[at], boundaries[at + 1]);
      const part = actual[at];
      if (part.segment !== expected || part.index !== boundaries[at] || part.input !== input ||
          part.index + part.segment.length !== boundaries[at + 1]) {
        throw new Error(`Node disagrees with GraphemeBreakTest ${DATA_VERSION} line ${index + 1}, segment ${at}: ` +
          `${literal(part.segment)} at ${part.index}, expected ${literal(expected)} at ${boundaries[at]}`);
      }
    }
    // Expectations are Node's outputs, independently checked above against
    // every break and non-break in the official conformance input.
    rows.push({ line: index + 1, input, boundaries: [...actual.map(part => part.index), input.length],
      expected: actual.map(part => part.segment) });
  }
  if (headerLines < 0 || rows.length === 0) throw new Error("Empty grapheme conformance input");
  return { header: lines.slice(0, headerLines).join("\n") + "\n", rows };
}

function cases(header: string, rows: Row[]): Map<string, string> {
  const files = new Map<string, string>();
  for (let offset = 0; offset < rows.length; offset += CHUNK_ROWS) {
    const chunk = rows.slice(offset, offset + CHUNK_ROWS);
    const first = chunk[0];
    const last = chunk[chunk.length - 1];
    const name = `${PREFIX}conformance-${String(offset / CHUNK_ROWS + 1).padStart(3, "0")}.ts`;
    const data = chunk.map(row => `  [${row.line}, ${literal(row.input)}, [${row.expected.map(literal).join(", ")}], [${row.boundaries.join(", ")}]],`).join("\n");
    const source = "/*---\n" +
      `description: GraphemeBreakTest ${DATA_VERSION} source lines ${first.line}-${last.line} agree with Node segments and UTF-16 boundaries.\n` +
      "features: [ts-unicode-graphemes, ts-strings, ts-iteration, ts-arrays, ts-tuples, ts-unicode-conformance]\n---*/\n" +
      `// Generated by tooling/unicode-cases/graphemes.ts; Node ${NODE}, Unicode ${UNICODE}, ICU ${ICU}.\n` +
      "// Contract: docs/foundations/unicode.md, Staying identical to node.\n" +
      `// Source: ${SOURCE}\n// SHA-256: ${SHA256}\n` +
      `// All ${chunk.length} rows in this chunk; every official test row appears exactly once.\n` +
      `/*\n${header}*/\n` +
      'const segmenter = new Intl.Segmenter("en", { granularity: "grapheme" });\n' +
      "const rows: [number, string, string[], number[]][] = [\n" + data + "\n];\n" +
      "for (const [line, input, expected, boundaries] of rows) {\n" +
      `  const label = "GraphemeBreakTest ${DATA_VERSION} line " + line;\n` +
      "  let index = 0;\n  let end = 0;\n" +
      "  for (const part of segmenter.segment(input)) {\n" +
      '    assert.sameValue(index < expected.length, true, label + " extra segment");\n' +
      '    assert.sameValue(part.segment, expected[index], label + " segment " + index);\n' +
      '    assert.sameValue(part.index, boundaries[index], label + " start " + index);\n' +
      '    assert.sameValue(part.segment.length, boundaries[index + 1] - boundaries[index], label + " length " + index);\n' +
      '    assert.sameValue(part.index + part.segment.length, boundaries[index + 1], label + " end " + index);\n' +
      '    assert.sameValue(part.input, input, label + " input " + index);\n' +
      "    end = part.index + part.segment.length;\n    index++;\n  }\n" +
      '  assert.sameValue(index, expected.length, label + " segment count");\n' +
      '  assert.sameValue(end, input.length, label + " complete coverage");\n' +
      '  assert.sameValue(input.length, boundaries[boundaries.length - 1], label + " final boundary");\n' +
      "}\n";
    files.set(name, source);
  }
  return files;
}

function writeOrCheck(files: Map<string, string>, check: boolean, output: string): void {
  const existing = existsSync(output) ? readdirSync(output).filter(name => name.startsWith(PREFIX) && name.endsWith(".ts")) : [];
  const problems: string[] = [];
  for (const name of existing) if (!files.has(name)) problems.push(`unexpected ${name}`);
  for (const [name, content] of files) {
    const path = join(output, name);
    if (existsSync(path)) {
      if (readFileSync(path, "utf8") !== content) problems.push(`differs ${name}`);
    } else if (check) problems.push(`missing ${name}`);
  }
  if (problems.length > 0) throw new Error(`Generated grapheme cases disagree; existing cases were not changed:\n${problems.join("\n")}`);
  if (!check) {
    mkdirSync(output, { recursive: true });
    for (const [name, content] of files) {
      const path = join(output, name);
      if (!existsSync(path)) writeFileSync(path, content, { encoding: "utf8", flag: "wx" });
    }
  }
}

async function main(): Promise<void> {
  requireOracle();
  const config = options();
  const { header, rows } = parseAndVerify(await sourceText(config.dataDir));
  const files = cases(header, rows);
  writeOrCheck(files, config.check, config.outputDir);
  console.log(JSON.stringify({ mode: config.check ? "checked" : "generated", node: NODE, unicode: UNICODE, icu: ICU,
    dataVersion: DATA_VERSION, source: SOURCE, sha256: SHA256, conformanceRows: rows.length,
    segments: rows.reduce((total, row) => total + row.expected.length, 0), cases: files.size }, null, 2));
}

main().catch((error: unknown) => { console.error(error instanceof Error ? error.message : String(error)); process.exitCode = 1; });
